#!/usr/bin/env node
/**
 * zk/scripts/publish-results-to-public.ts
 *
 * Step 2.13: Publish canonical results.json to a Vercel-friendly static location.
 *
 * Rationale:
 * - BotoVeritas frontend is Vite+React hosted on Vercel.
 * - Anything under /public is served as a static file at the site root.
 * - This lets `ElectionTallyRegistry.resultsUri` point to a stable URL like:
 *     https://<your-app-domain>/zk-results/<key>.json
 *
 * Inputs:
 * - results.json generated by build-results-json.ts (BV_RESULTS_JSON_V1)
 *
 * Behavior:
 * - Computes a stable filename using the on-chain key basis:
 *     key = keccak256(electionIdHashBytes32 + electionVoteRootBytes32)  (hex string concatenation)
 *   We mirror the on-chain tallyKey concept so the URL is deterministic.
 * - Copies the file to:
 *     public/zk-results/<key>.json
 * - Prints the final `resultsUri` based on PUBLIC_BASE_URL
 *
 * Usage:
 *   node zk/scripts/publish-results-to-public.ts --in <results.json>
 *
 * Optional:
 *   PUBLIC_BASE_URL="https://your-vercel-domain"  (recommended for printing the final URI)
 */

import fs from "node:fs";
import path from "node:path";
import crypto from "node:crypto";

type ResultsJson = {
  schema: string;
  anchors: {
    electionIdHashBytes32: string;
    electionVoteRootBytes32: string;
    manifestHashBytes32: string;
    resultsHashBytes32: string;
  };
};

function parseArgs(argv: string[]) {
  const args: { in?: string } = {};
  for (let i = 2; i < argv.length; i++) {
    const a = argv[i];
    if (a === "--in") args.in = argv[++i];
  }
  return args;
}

function readJson<T>(p: string): T {
  return JSON.parse(fs.readFileSync(p, "utf8")) as T;
}

function normalize0x32(hex: string): string {
  const s = hex.trim().toLowerCase();
  if (!s.startsWith("0x")) throw new Error(`Expected 0x-prefixed hex: ${hex}`);
  const body = s.slice(2);
  if (body.length != 64) throw new Error(`Expected 32-byte hex (64 nibbles): ${hex}`);
  return body;
}

// NOTE: Solidity uses keccak256(abi.encodePacked(bytes32,bytes32))
// For bytes32 values, abi.encodePacked is simple concatenation of 32-byte sequences.
// We mirror that here.
function computeTallyKey(electionIdHashBytes32: string, electionVoteRootBytes32: string): string {
  const a = Buffer.from(normalize0x32(electionIdHashBytes32), "hex");
  const b = Buffer.from(normalize0x32(electionVoteRootBytes32), "hex");
  const packed = Buffer.concat([a, b]);
  return "0x" + crypto.createHash("keccak256").update(packed).digest("hex");
}

// Node crypto doesn't include keccak256 by default in some environments.
// We provide a fallback using sha3-256 only for dev visibility, but for correctness you MUST
// have keccak256. Easiest: use ethers (recommended) or install keccak.
// We'll implement keccak via ethers if available at runtime.
async function computeTallyKeySafe(electionIdHashBytes32: string, electionVoteRootBytes32: string): Promise<string> {
  try {
    // @ts-ignore - ethers may be present in hardhat environments
    const ethers: any = await import("ethers");
    const packed = ethers.solidityPacked(["bytes32", "bytes32"], [electionIdHashBytes32, electionVoteRootBytes32]);
    return ethers.keccak256(packed);
  } catch {
    // Fallback: try node crypto with 'keccak256' (may throw if unsupported)
    try {
      const a = Buffer.from(normalize0x32(electionIdHashBytes32), "hex");
      const b = Buffer.from(normalize0x32(electionVoteRootBytes32), "hex");
      const packed = Buffer.concat([a, b]);
      // @ts-ignore
      return "0x" + crypto.createHash("keccak256").update(packed).digest("hex");
    } catch (e) {
      throw new Error(
        "Unable to compute keccak256. Install ethers (already present if you use Hardhat) or add a keccak library."
      );
    }
  }
}

async function main() {
  const { in: inPath } = parseArgs(process.argv);
  if (!inPath) {
    console.error("Usage: publish-results-to-public --in <results.json>");
    process.exit(1);
  }

  const r = readJson<ResultsJson>(inPath);
  if (r.schema !== "BV_RESULTS_JSON_V1") throw new Error("Unsupported schema (expected BV_RESULTS_JSON_V1)");

  const key = await computeTallyKeySafe(r.anchors.electionIdHashBytes32, r.anchors.electionVoteRootBytes32);

  const outDir = path.join("public", "zk-results");
  const outPath = path.join(outDir, `${key}.json`);
  fs.mkdirSync(outDir, { recursive: true });
  fs.copyFileSync(inPath, outPath);

  const baseUrl = (process.env.PUBLIC_BASE_URL ?? "").trim().replace(/\/$/, "");
  const resultsUri = baseUrl ? `${baseUrl}/zk-results/${key}.json` : `/zk-results/${key}.json`;

  console.log("Published:", outPath);
  console.log("resultsUri:", resultsUri);
  console.log("tallyKey:", key);
}

main().catch((e) => {
  console.error(String(e));
  process.exit(1);
});
